// Write semantics and rules of the NAS copy's write route: app writes → ops, Firestore-like merges, a copy of the Firestore rules, and the whole route logic over a small store.
// Pure and shared: the phone (ticket 05) and PocketBase's write route `POST /api/pm/save` run the same code; the hook runs the CommonJS copy
// pb/pb_hooks/pm/pbwrite.js generated by scripts/pb-hooks-build.mjs (coding-standards rule 15). Spec 4 § 2.3–2.4, ADR 0020; checked by tests/pbwrite.test.js.
// Syntax PocketBase's JS engine runs: no optional chaining, no `??`, no object spread, no imports; `export` only on top-level
// functions and constants (the generator turns them into `module.exports`).
//
// Contents:
// - constants — PB_SCHEMA, MIN_CLIENT_SCHEMA, POOL_KINDS, limits
// - toOps(kind, pid, writes) — the writes of the repo backends (commit, commitPool, setInbox, allowEmails, saveUserPrefs) as ops
// - merges — mergeDeep, mergeFields, applyArrayOps, applyItemPatches, mergeDoc
// - rules — validateOp, checkOp, changedKeys, invitesOf, membersOf
// - runSave(store, env, request) — the route: schema check, ops in order, the first refusal stops everything

// ---------- constants ----------

// The server's schema version (CONTEXT.md «Schema version»); equals PM_SCHEMA of pb/pb_hooks/pm.pb.js and `schema` of nas-site.json
export const PB_SCHEMA = 1;
// The oldest app schema the server still serves; an older app gets 426 `app_old`
export const MIN_CLIENT_SCHEMA = 1;
// Kinds of the `pool` collection (spec § 2.1); a new kind needs a rule below and a schema step
export const POOL_KINDS = ['types', 'devices', 'cables', 'catalog', 'manuals', 'doorcfg', 'delayReasons', 'culprits', 'problems'];
export const MAX_OPS = 500;
export const MAX_PROJECT_KEY = 64;
export const MAX_KEY = 400;
export const COLL_RE = /^[A-Za-z]{1,40}$/;

// Pool kinds only the administrator writes; kinds any allowed user writes but only the administrator marks deleted
const ADMIN_KINDS = ['types', 'devices', 'cables', 'catalog'];
const SHARED_KINDS = ['doorcfg', 'delayReasons', 'culprits', 'problems'];
// Project keys only the creator changes; the only keys an invitee changes (Firestore's `updatedAtServer` is not stored here)
const CREATOR_KEYS = ['memberUids', 'memberEmails', 'invitedEmails', 'removedMembers', 'createdBy', 'archived', 'deleted'];
const INVITEE_KEYS = ['memberUids', 'memberEmails', 'invitedEmails', 'updatedAt', 'updatedBy', 'updatedByName'];
// Inbox keys only the administrator changes (the decision on an item)
const INBOX_ADMIN_KEYS = ['status', 'seenHash', 'seenItem', 'seenAt'];

// ---------- small helpers ----------

function isPlain(v) { return v !== null && typeof v === 'object' && !Array.isArray(v); }
function clone(v) { return v === undefined ? undefined : JSON.parse(JSON.stringify(v)); }
function lower(s) { return String(s == null ? '' : s).toLowerCase(); }
function has(list, v) { return list.indexOf(v) >= 0; }
function copyWithout(obj, drop) {
  const out = {};
  Object.keys(obj || {}).forEach(function (k) { if (!has(drop, k)) out[k] = obj[k]; });
  return out;
}
// Deep equality of JSON values: objects regardless of key order, arrays by position
export function deepEqual(a, b) {
  if (a === b) return true;
  if (Array.isArray(a) || Array.isArray(b)) {
    if (!Array.isArray(a) || !Array.isArray(b) || a.length !== b.length) return false;
    for (let i = 0; i < a.length; i++) if (!deepEqual(a[i], b[i])) return false;
    return true;
  }
  if (!isPlain(a) || !isPlain(b)) return false;
  const ka = Object.keys(a); const kb = Object.keys(b);
  if (ka.length !== kb.length) return false;
  for (let i = 0; i < ka.length; i++) if (!Object.prototype.hasOwnProperty.call(b, ka[i]) || !deepEqual(a[ka[i]], b[ka[i]])) return false;
  return true;
}

// ---------- app writes → ops ----------

// kind 'commit': [{coll, id, data, replace?, arrayOps?}] of one project (coll 'projects' is the project document, 'history' its history);
// 'commitPool': [{coll: <pool kind>, id, data?, remove?}]; 'setInbox': [{key, data}]; 'allowEmails': ['<e-mail>'];
// 'saveUserPrefs': [{data, replace?}]. Firestore's `updatedAtServer` is dropped: PocketBase's `updated` plays its part.
export function toOps(kind, pid, writes) {
  const list = writes || [];
  if (kind === 'commit') return list.map(function (w) { return commitOp(pid, w); });
  if (kind === 'commitPool') {
    return list.map(function (w) {
      return w.remove ? { t: 'pool', kind: w.coll, key: String(w.id), remove: true }
        : { t: 'pool', kind: w.coll, key: String(w.id), data: cleanData(w.data, null) };
    });
  }
  if (kind === 'setInbox') return list.map(function (x) { return { t: 'inbox', key: String(x.key), data: cleanData(x.data, null) }; });
  if (kind === 'allowEmails') return list.map(function (e) { return { t: 'allowed', email: lower(e).trim() }; });
  if (kind === 'saveUserPrefs') return list.map(function (w) { return { t: 'prefs', data: cleanData(w.data, null), mode: w.replace ? 'fields' : 'deep' }; });
  throw new Error('toOps: unknown kind ' + kind);
}

function cleanData(data, arrayOps) {
  // Firestore's commit puts the array transform in place of the field's value: the value of such a field is never written
  const drop = ['updatedAtServer'].concat(Object.keys(arrayOps || {}));
  return clone(copyWithout(data, drop));
}

function commitOp(pid, w) {
  const arrayOps = w.arrayOps && Object.keys(w.arrayOps).length ? clone(w.arrayOps) : null;
  const data = cleanData(w.data, arrayOps);
  let op;
  if (w.coll === 'projects') op = { t: 'project', key: String(w.id), data: data, mode: w.replace ? 'fields' : 'deep' };
  else if (w.coll === 'history') return { t: 'history', pid: String(pid), key: String(w.id), data: data };
  // points are always written whole by top-level fields (`pos` is not merged with the old one), as in createFirestoreBackend
  else op = { t: 'rec', pid: String(pid), coll: w.coll, key: String(w.id), data: data, mode: w.replace || w.coll === 'points' ? 'fields' : 'deep' };
  if (arrayOps) op.arrayOps = arrayOps;
  return op;
}

// ---------- merges (Firestore's set semantics) ----------

// `set(…, {merge: true})`: plain objects merge key by key, recursively; arrays, scalars and null replace;
// an empty object replaces (Firestore treats it as a leaf); keys the write does not carry stay
export function mergeDeep(old, data) {
  const out = isPlain(old) ? clone(old) : {};
  Object.keys(data || {}).forEach(function (k) {
    const v = data[k];
    if (isPlain(v) && Object.keys(v).length && isPlain(out[k])) out[k] = mergeDeep(out[k], v);
    else if (isPlain(v) && Object.keys(v).length) out[k] = mergeDeep({}, v);
    else out[k] = clone(v);
  });
  return out;
}

// `set(…, {mergeFields: Object.keys(data)})`: each top-level key of the write replaces that key whole
export function mergeFields(old, data) {
  const out = isPlain(old) ? clone(old) : {};
  Object.keys(data || {}).forEach(function (k) { out[k] = clone(data[k]); });
  return out;
}

// arrayUnion / arrayRemove: `union` appends the values not present yet, in order; `remove` drops every equal value;
// a field that is not an array becomes one (as Firestore does)
export function applyArrayOps(doc, arrayOps) {
  const out = clone(doc) || {};
  Object.keys(arrayOps || {}).forEach(function (k) {
    const o = arrayOps[k];
    let cur = Array.isArray(out[k]) ? out[k] : [];
    if (Array.isArray(o.union)) o.union.forEach(function (v) { if (!cur.some(function (x) { return deepEqual(x, v); })) cur.push(clone(v)); });
    if (Array.isArray(o.remove)) cur = cur.filter(function (x) { return !o.remove.some(function (v) { return deepEqual(x, v); }); });
    out[k] = cur;
  });
  return out;
}

// Jobs only: { <list>: { <item id>: {fields} } } merges the fields into the list item with that id; unknown ids are ignored
export function applyItemPatches(doc, itemPatches) {
  const out = clone(doc) || {};
  Object.keys(itemPatches || {}).forEach(function (list) {
    const patches = itemPatches[list];
    if (!Array.isArray(out[list])) return;
    out[list] = out[list].map(function (item) {
      if (!isPlain(item) || !Object.prototype.hasOwnProperty.call(patches, item.id)) return item;
      return mergeFields(item, patches[item.id]);
    });
  });
  return out;
}

// The document to save for an op on top of the stored one (null = missing; a missing target is created from the write).
// A history op on an existing entry returns the stored entry unchanged (create only).
export function mergeDoc(old, op) {
  if (op.t === 'history') return old ? clone(old) : clone(op.data);
  if (op.t === 'allowed') return old ? clone(old) : { email: lower(op.email) };
  const data = op.t === 'pool' && op.remove ? { deleted: true } : op.data;
  let doc = op.mode === 'fields' ? mergeFields(old, data) : mergeDeep(old, data);
  if (op.arrayOps) doc = applyArrayOps(doc, op.arrayOps);
  if (op.itemPatches) doc = applyItemPatches(doc, op.itemPatches);
  return doc;
}

// ---------- rules ----------

function refuse(code, message) { return { ok: false, code: code, message: message }; }
const OK = { ok: true };

function badKey(v, max) { return typeof v !== 'string' || !v.length || v.length > max; }

// Shape of one op: { ok } or a refusal with code 'invalid'
export function validateOp(op) {
  if (!isPlain(op)) return refuse('invalid', 'op is not an object');
  const t = op.t;
  const needsData = t === 'project' || t === 'rec' || t === 'history' || t === 'inbox' || t === 'prefs' || (t === 'pool' && !op.remove);
  if (needsData && !isPlain(op.data)) return refuse('invalid', 'data is not an object');
  if ((t === 'project' || t === 'rec' || t === 'prefs') && op.mode !== 'deep' && op.mode !== 'fields') return refuse('invalid', 'bad mode');
  if (t === 'project') {
    if (badKey(op.key, MAX_PROJECT_KEY)) return refuse('invalid', 'bad project key');
  } else if (t === 'rec' || t === 'history') {
    if (badKey(op.pid, MAX_PROJECT_KEY)) return refuse('invalid', 'bad project key');
    if (badKey(op.key, MAX_KEY)) return refuse('invalid', 'bad key');
    if (t === 'rec' && (typeof op.coll !== 'string' || !COLL_RE.test(op.coll) || op.coll === 'projects' || op.coll === 'history')) return refuse('invalid', 'bad collection name');
  } else if (t === 'pool') {
    if (!has(POOL_KINDS, op.kind)) return refuse('invalid', 'unknown pool kind');
    if (badKey(op.key, MAX_KEY)) return refuse('invalid', 'bad key');
  } else if (t === 'inbox') {
    if (badKey(op.key, MAX_KEY)) return refuse('invalid', 'bad key');
  } else if (t === 'allowed') {
    if (badKey(op.email, MAX_KEY) || op.email.indexOf('@') < 1) return refuse('invalid', 'bad e-mail');
  } else if (t !== 'prefs') {
    return refuse('invalid', 'unknown op');
  }
  if (op.arrayOps !== undefined) {
    if (!isPlain(op.arrayOps)) return refuse('invalid', 'bad arrayOps');
    const keys = Object.keys(op.arrayOps);
    for (let i = 0; i < keys.length; i++) {
      const o = op.arrayOps[keys[i]];
      if (!isPlain(o) || (Array.isArray(o.union) === Array.isArray(o.remove))) return refuse('invalid', 'bad arrayOps.' + keys[i]);
    }
  }
  if (op.itemPatches !== undefined) {
    if (t !== 'project' || !isPlain(op.itemPatches)) return refuse('invalid', 'bad itemPatches');
    const lists = Object.keys(op.itemPatches);
    for (let i = 0; i < lists.length; i++) if (!isPlain(op.itemPatches[lists[i]])) return refuse('invalid', 'bad itemPatches.' + lists[i]);
  }
  return OK;
}

// Top-level keys that differ between the stored and the merged document (Firestore's `diff().affectedKeys()`)
export function changedKeys(oldDoc, newDoc) {
  const a = oldDoc || {}; const b = newDoc || {};
  const keys = Object.keys(a).concat(Object.keys(b).filter(function (k) { return !Object.prototype.hasOwnProperty.call(a, k); }));
  return keys.filter(function (k) { return !deepEqual(a[k], b[k]); });
}

function lowerList(v) { return Array.isArray(v) ? v.map(lower) : []; }

function isAdmin(env) { return !!env.adminEmail && !!env.user && lower(env.adminEmail) === lower(env.user.email); }
function isAllowedUser(env) { return isAdmin(env) || (!!env.user && !!env.isAllowed(lower(env.user.email))); }

// One op against the rules of spec § 2.4 (a copy of firestore.rules). env = {user: {id, email}, isSuper, adminEmail,
// isAllowed(email), project(pid)}; project(pid) gives the project as of this point of the request (null = none).
// Returns { ok: true } or { ok: false, code: 'forbidden' | 'not-found' | 'invalid', message }.
export function checkOp(env, op, oldDoc, newDoc) {
  const v = validateOp(op);
  if (!v.ok) return v;
  if (env.isSuper) return OK;
  if (!env.user || !env.user.id) return refuse('forbidden', 'not signed in');
  if (op.itemPatches) return refuse('forbidden', 'itemPatches are for server jobs only');
  const uid = env.user.id; const email = lower(env.user.email);
  if (op.t === 'project') return checkProject(env, uid, email, oldDoc, newDoc);
  if (op.t === 'rec' || op.t === 'history') {
    const p = env.project(op.pid);
    if (!p) return refuse('not-found', 'project not found');
    return has(p.memberUids || [], uid) ? OK : refuse('forbidden', 'not a member of the project');
  }
  if (op.t === 'pool') {
    if (isAdmin(env)) return OK;
    if (has(ADMIN_KINDS, op.kind)) return refuse('forbidden', 'only the administrator writes pool ' + op.kind);
    if (!isAllowedUser(env)) return refuse('forbidden', 'not in the allowed list');
    if (op.kind === 'manuals') return OK;
    // Firestore: `request.resource.data.get('deleted', false) == false`
    const d = (newDoc || {}).deleted;
    return d === undefined || d === false ? OK : refuse('forbidden', 'only the administrator marks deleted');
  }
  if (op.t === 'inbox') {
    if (!oldDoc) return isAllowedUser(env) ? OK : refuse('forbidden', 'not in the allowed list');
    if (isAdmin(env)) return OK;
    if (!isAllowedUser(env)) return refuse('forbidden', 'not in the allowed list');
    const ch = changedKeys(oldDoc, newDoc);
    return INBOX_ADMIN_KEYS.some(function (k) { return has(ch, k); }) ? refuse('forbidden', 'only the administrator decides on inbox items') : OK;
  }
  if (op.t === 'allowed') return isAdmin(env) ? OK : refuse('forbidden', 'only the administrator writes the allowed list');
  if (op.t === 'prefs') return OK;
  return refuse('invalid', 'unknown op');
}

function checkProject(env, uid, email, oldDoc, newDoc) {
  if (!oldDoc) {
    if (!isAllowedUser(env)) return refuse('forbidden', 'not in the allowed list');
    return has((newDoc || {}).memberUids || [], uid) ? OK : refuse('forbidden', 'the creator is not a member of the new project');
  }
  const ch = changedKeys(oldDoc, newDoc);
  const oldUids = oldDoc.memberUids || [];
  if (has(oldUids, uid)) {
    const creator = oldDoc.createdBy === undefined || oldDoc.createdBy === null ? uid : oldDoc.createdBy;
    if (creator === uid) return OK;
    return CREATOR_KEYS.some(function (k) { return has(ch, k); }) ? refuse('forbidden', 'only the project creator changes members and invitations') : OK;
  }
  if (email && has(lowerList(oldDoc.invitedEmails), email)) {
    if (!ch.every(function (k) { return has(INVITEE_KEYS, k); })) return refuse('forbidden', 'an invitee only accepts or declines');
    const newUids = (newDoc || {}).memberUids || [];
    const accept = newUids.length === oldUids.length + 1 && has(newUids, uid) && oldUids.every(function (x) { return has(newUids, x); });
    const decline = deepEqual(newUids, oldUids);
    return accept || decline ? OK : refuse('forbidden', 'an invitee adds only themself');
  }
  return refuse('forbidden', 'not a member of the project');
}

// The `invites` index of a project (spec § 2.4, step 5): one entry per invited e-mail in lower case
export function invitesOf(project) {
  const p = project || {}; const seen = []; const out = [];
  const from = Array.isArray(p.memberEmails) && p.memberEmails.length ? lower(p.memberEmails[0]) : '';
  (Array.isArray(p.invitedEmails) ? p.invitedEmails : []).forEach(function (e) {
    const em = lower(e).trim();
    if (!em || has(seen, em)) return;
    seen.push(em);
    out.push({ email: em, name: String(p.name || ''), object: String(p.object || ''), from: from });
  });
  return out;
}

// The `members` relation of a project record: the user ids of `memberUids`, each once
export function membersOf(project) {
  const out = [];
  ((project || {}).memberUids || []).forEach(function (u) { if (typeof u === 'string' && u && !has(out, u)) out.push(u); });
  return out;
}

// ---------- the route ----------

// Where an op lands, in the terms of spec § 2.1; `id` is the request-local identity of the target
function targetOf(env, op) {
  if (op.t === 'project') return { c: 'projects', key: op.key };
  if (op.t === 'rec') return { c: 'records', pid: op.pid, coll: op.coll, key: op.key };
  if (op.t === 'history') return { c: 'history', pid: op.pid, key: op.key };
  if (op.t === 'pool') return { c: 'pool', kind: op.kind, key: op.key };
  if (op.t === 'inbox') return { c: 'inbox', key: op.key };
  if (op.t === 'allowed') return { c: 'allowed', email: lower(op.email) };
  // prefs: the signed-in user's own record; a superuser (the restore tool) names the user
  if (op.t === 'prefs') return { c: 'prefs', user: env.isSuper && op.user ? String(op.user) : (env.user ? env.user.id : '') };
  return null;
}
function idOf(target) { return JSON.stringify(target); }

function answer(status, code, index, message) { return { status: status, code: code, index: index, message: message }; }

// The whole route logic. store = { find(target) → stored data or null, put(target, data, derived), setInvites(pid, invites),
// optional begin(), commit(), rollback() }; derived = { members } for a project, { at } for a history entry.
// request = { schema, ops }. Nothing is written until every op has passed; then the writes go out in op order.
// Answers: { status: 200, ok: true, n }, { status: 409, code: 'schema_old', schema }, { status: 426, code: 'app_old' },
// { status: 422, code, index, message } (index -1 = the request as a whole).
export function runSave(store, env, request) {
  const req = isPlain(request) ? request : {};
  const schema = typeof req.schema === 'number' ? req.schema : 0;
  if (schema > PB_SCHEMA) return { status: 409, code: 'schema_old', schema: PB_SCHEMA };
  if (schema < MIN_CLIENT_SCHEMA) return { status: 426, code: 'app_old' };
  if (!Array.isArray(req.ops)) return answer(422, 'invalid', -1, 'ops is not a list');
  if (req.ops.length > MAX_OPS) return answer(422, 'invalid', -1, 'more than ' + MAX_OPS + ' ops');

  const seen = {}; // target id → the document as of this point of the request (null = missing)
  function load(target) {
    const id = idOf(target);
    if (!Object.prototype.hasOwnProperty.call(seen, id)) { const d = store.find(target); seen[id] = d === undefined ? null : d; }
    return seen[id];
  }
  const ctx = {
    user: env.user || null, isSuper: !!env.isSuper, adminEmail: env.adminEmail || '',
    isAllowed: env.isAllowed || function () { return false; },
    project: function (pid) { return load({ c: 'projects', key: String(pid) }); },
  };

  const writes = [];
  for (let i = 0; i < req.ops.length; i++) {
    const op = req.ops[i];
    const v = validateOp(op);
    if (!v.ok) return answer(422, v.code, i, v.message);
    const target = targetOf(ctx, op);
    if (op.t === 'prefs' && !target.user) return answer(422, ctx.isSuper ? 'invalid' : 'forbidden', i, 'no user for prefs');
    const old = load(target);
    // create only: a history entry or an allowed e-mail already there is a resend, success without a write
    if (old && (op.t === 'history' || op.t === 'allowed')) {
      const r0 = checkOp(ctx, op, old, old); // still only for those who may write it
      if (!r0.ok) return answer(422, r0.code, i, r0.message);
      continue;
    }
    const doc = mergeDoc(old, op);
    const r = checkOp(ctx, op, old, doc);
    if (!r.ok) return answer(422, r.code, i, r.message);
    seen[idOf(target)] = doc;
    const derived = op.t === 'project' ? { members: membersOf(doc) } : op.t === 'history' ? { at: Number(doc.at) || 0 } : {};
    writes.push({ index: i, target: target, data: doc, derived: derived });
    if (op.t === 'project') writes.push({ index: i, invites: true, pid: op.key, list: invitesOf(doc) });
  }

  if (store.begin) store.begin();
  for (let j = 0; j < writes.length; j++) {
    const w = writes[j];
    try {
      if (w.invites) store.setInvites(w.pid, w.list);
      else store.put(w.target, w.data, w.derived);
    } catch (e) {
      if (store.rollback) store.rollback();
      return answer(422, 'invalid', w.index, String((e && e.message) || e));
    }
  }
  if (store.commit) store.commit();
  return { status: 200, ok: true, n: req.ops.length };
}
